import{_ as t,l as o,o as a,c as s,v as n,p as l,x as i,d as p,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"风险转移","description":"","frontmatter":{"title":"风险转移","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/risk-shifting.md","filePath":"econ/risk-shifting.md","lastUpdated":1789023840000}'),c={name:"econ/risk-shifting.md"};function h(B,e,A,_,m,f){const r=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=n('<h1 id="风险转移" tabindex="-1">风险转移 <a class="header-anchor" href="#风险转移" aria-label="Permalink to &quot;风险转移&quot;">​</a></h1><div class="epigraph"><p>股权是对企业资产的看涨期权；加大资产波动，期权更贵，债权人承担下行——这是资产替代，不是投资不足。</p><footer>—— Jensen and Meckling, Theory of the Firm: Managerial Behavior, Agency Costs and Ownership Structure, Journal of Financial Economics, 1976</footer></div><p><a href="/econ/debt-overhang">上一课</a>给出股东放弃正 NPV 的积压。同一张看涨期权还有另一面：不放弃行权，而是改项目分布，把方差加大。本课缺口是 Jensen–Meckling 的资产替代（风险转移）。不重推 Myers 的增长期权税，不把优序提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>积压是「好项目也不做」。观察上杠杆企业也可以做得更险：合并风险业务、减少对冲、把安全资产换成彩票。Jensen 与 Meckling（1976）把股权写成看涨：面值是执行价，资产是标的。期权对波动升值，债权对波动贬值。经理若代表股东，就有激励在债务已定价之后把资产变险——风险从债转移到股。</p><p>缺口是把权衡右边的事前间接再补一条，方向与积压相反：一个是投资过少，一个是风险过多。债权人若预期到替代，会在事前利率里收费，杠杆的好处再被削一截。下一课优序换信息不对称下的发行顺序，不再增加代理扭曲的品种。</p><p><span class="marginnote">资产替代、风险转移、赌大的：同一机制。对象是已有债的持有期里改变资产方差，不是发行时的柠檬折价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把杠杆企业的股权价值当看涨期权（Merton 结构模型的精神，本课不估信用利差）。波动上升，股权升、债降，企业总价值可以因错误项目而下降，但股权仍升——转移成功。约束：债契约、保护性条款、短期滚动、可转债，都能削弱激励。Jensen–Meckling 同时写经理–股东冲突（在职消费）；本课只取股东–债权人这一刀，以免与自由现金流课抢定义。</p>',9)),(a(),l(d,null,{default:i(()=>[E(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E8%82%A1%E6%9D%83%20%3D%20%E7%9C%8B%E6%B6%A8%22%5D%20--%3E%20VOL%5B%22%E6%8F%90%E9%AB%98%E8%B5%84%E4%BA%A7%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20VOL%20--%3E%20EQUP%5B%22%E8%82%A1%E6%9D%83%E5%8D%87%E5%80%BC%22%5D%0A%20%20VOL%20--%3E%20BD%5B%22%E5%80%BA%E6%9D%83%E8%B4%AC%E5%80%BC%22%5D%0A%20%20BD%20--%3E%20AGENCY%5B%22%E4%BB%A3%E7%90%86%E6%88%90%E6%9C%AC%3A%20%E6%80%BB%E4%BB%B7%E5%80%BC%E5%8F%AF%E9%99%8D%22%5D%0A%20%20OV%5B%22%E7%A7%AF%E5%8E%8B%3A%20%E6%94%BE%E5%BC%83%E6%AD%A3%20NPV%22%5D%20--%3E%20OTHER%5B%22%E5%8F%A6%E4%B8%80%E6%96%B9%E5%90%91%2C%20%E4%B8%8A%E4%B8%80%E8%AF%BE%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<p>积压与转移可以共存：安全的正 NPV 被放弃，彩票项目被接受。权衡若只盯立案费用，两条都漏。</p><h3 id="保险期权与本课同构" tabindex="-1">保险期权与本课同构 <a class="header-anchor" href="#保险期权与本课同构" aria-label="Permalink to &quot;保险期权与本课同构&quot;">​</a></h3><p>存款保险课会把看跌写在保险基金上。这里看跌的对手是私人债权人。机制同构：下行外包，上行留下。不要把两课合成一句「杠杆总是赌」——对手方不同，约束不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是有限责任加不可签约的投资分布。合同很难写死「方差上限」：项目选择、对冲、会计科目都可以改风险。债一旦借出，再谈判成本高，股东的最优是把财富从债口袋挪到股口袋。事前，债权人要求更高利息或更严条款，把预期转移写进价格，于是 \\(V_L\\) 相对无摩擦下降——这是代理成本，不是税收。</p><p>与 Myers 积压的对照：积压发生在需要<strong>新股权</strong>去执行好期权时；转移发生在<strong>已有资产</strong>可被替换时。一个要股东掏钱，一个要股东换彩票。条款设计对两者的药不同：缩短期限、抵押、可转债（后课 Stein）对转移更直接。</p><p><span class="marginnote">Jensen and Meckling, <em>JFE</em> 1976。看涨类比是教学装置；不必在此校准隐含波动。信用利差的结构模型实证换栏或不做，本课只要激励方向。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把所有高风险企业都叫风险转移：成长企业方差大可以是技术，不是为了掏债权人。也不要把资产替代写成交易员的限价簿策略。下一课 <a href="/econ/pecking-order">优序融资</a>换柠檬：经理相对市场的信息，而不是股东相对债权人的期权。</p><p>后课默认：杠杆股权有激励加大资产风险；债权人事前收费。积压与转移是间接困境成本的两个方向，直接律师费仍往往不够挡税盾。</p><p>MM 无摩擦世界里没有转移：条款可无成本写死，或再谈判到第一最佳。本课的对象是写不完、谈不成的分布。</p><p>可转债、认股权证让债权人分享上行，转移的好处变小；这是后课 Stein 的旁支，本课先把看涨激励钉在普通债上。抵押把方差锁在特定资产上，替代空间变窄，却把火线出售的对象写得更清楚。</p><p>优序下一课换的是经理对市场的柠檬，不是股东对债权人的期权。两套信息不对称不要写成一句。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>风险转移：股权作为看涨，激励在债已定价后加大资产波动。</li><li>与债务积压方向相反：一个放弃好项目，一个接受更险的项目。</li><li>条款与期限是约束，不是把代理成本从权衡里删掉。</li><li>下一课优序换经理对市场的柠檬，不再增加股东–债权人扭曲的品种。</li><li>可转债分享上行，是后课对转移的合同补丁，不是本课主线。</li><li>出处：Jensen and Meckling, <em>JFE</em> 1976；对照 Myers 1977。</li></ul>',15))])}const k=t(c,[["render",h]]);export{g as __pageData,k as default};
